create table public.cda_orc_padroes_tipo(id uuid primary key default gen_random_uuid(),tipo_id uuid not null references public.cda_orc_tipos_projeto(id),chave text not null,conteudo jsonb not null default '{}',atualizado_em timestamptz not null default now(),unique(tipo_id,chave));
alter table public.cda_orc_padroes_tipo enable row level security;grant select,insert,update on public.cda_orc_padroes_tipo to authenticated;revoke all on public.cda_orc_padroes_tipo from anon;
create policy leitura on public.cda_orc_padroes_tipo for select to authenticated using (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))));
create policy inclusao on public.cda_orc_padroes_tipo for insert to authenticated with check (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
create policy edicao on public.cda_orc_padroes_tipo for update to authenticated using (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita')) with check (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
insert into public.cda_orc_padroes_tipo(tipo_id,chave,conteudo) select id,'premissas','{"publico_total":400000,"shows":10,"cenarios":[{"nome":"Pessimista","conversao":5},{"nome":"Conservador","conversao":7},{"nome":"Otimista","conversao":9}]}'::jsonb from public.cda_orc_tipos_projeto where codigo=1;
insert into public.cda_orc_padroes_tipo(tipo_id,chave,conteudo) select id,'dimensionamento','{"capacidade_loja":500,"area_loja":25,"compradores_vendedor":125,"estoquistas_loja":1,"apoio_loja":1,"apoio_evento":0,"arredondamento":"cima"}'::jsonb from public.cda_orc_tipos_projeto where codigo=1;
insert into public.cda_orc_padroes_tipo(tipo_id,chave,conteudo) select id,'funcoes','[{"nome":"Vendedores","unidade":"profissional/show","valor_unitario":300},{"nome":"Estoquista","unidade":"profissional/show","valor_unitario":300},{"nome":"Apoio","unidade":"profissional/show","valor_unitario":300},{"nome":"Designer","unidade":"profissional/show","valor_unitario":500},{"nome":"Supervisores","unidade":"profissional/show","valor_unitario":500},{"nome":"Filmmaker","unidade":"profissional/show","valor_unitario":500}]'::jsonb from public.cda_orc_tipos_projeto where codigo=1;
insert into public.cda_orc_padroes_tipo(tipo_id,chave,conteudo) select id,'calculos','{"modalidades":["Percentual","Valor fixo","Quantidade × valor unitário"],"bases":["Venda bruta","Venda após desconto comercial","Venda após descontos comerciais e financeiros","Resultado distribuível"]}'::jsonb from public.cda_orc_tipos_projeto where codigo=1;
insert into public.cda_orc_padroes_tipo(tipo_id,chave,conteudo) select id,'produtos','[]'::jsonb from public.cda_orc_tipos_projeto where codigo=1;
insert into public.cda_orc_padroes_tipo(tipo_id,chave,conteudo) select id,'participantes','[]'::jsonb from public.cda_orc_tipos_projeto where codigo=1;
insert into public.cda_orc_padroes_tipo(tipo_id,chave,conteudo) select id,'participacao','{"regras":[{"nome":"Participação cultural","percentual":25,"base":"Venda após descontos comerciais e financeiros"},{"nome":"Administração Direta","percentual":10,"base":"Venda bruta"},{"nome":"Administração Indireta","percentual":2.5,"base":"Venda bruta"},{"nome":"Parceiro Fabricação — resultado","percentual":50,"base":"Resultado distribuível"},{"nome":"Ciclo Arte — resultado","percentual":50,"base":"Resultado distribuível"}]}'::jsonb from public.cda_orc_tipos_projeto where codigo=1;
insert into public.cda_orc_padroes_tipo(tipo_id,chave,conteudo) select t.id,k,'{}'::jsonb from public.cda_orc_tipos_projeto t cross join unnest(array['premissas','dimensionamento','funcoes','calculos','produtos','participantes','participacao']) k on conflict(tipo_id,chave) do nothing;
create or replace function public.cda_orc_previa_cadastros(vinculo uuid) returns table(chave text,conteudo jsonb) language sql security invoker set search_path=public as $$
with v as(select * from public.cda_orc_projeto_tipos where id=vinculo and ativo)
select 'categorias',coalesce((select jsonb_agg(to_jsonb(c) order by string_to_array(c.codigo,'.')::int[]) from public.cda_orc_categorias c where c.tipo_id=(select tipo_id from v) and c.ativo),'[]'::jsonb)
union all select k,coalesce(p.conteudo,'{}'::jsonb) from unnest(array['premissas','dimensionamento','funcoes','calculos','produtos','participantes','participacao']) k left join public.cda_orc_padroes_tipo p on p.chave=k and p.tipo_id=(select tipo_id from v);
$$;
create function public.cda_orc_salvar_cadastro(escopo text,registro uuid,anterior jsonb,novo jsonb) returns boolean language plpgsql security invoker set search_path=public as $$ declare n integer;begin
if jsonb_typeof(novo) not in ('object','array') then raise exception 'Estrutura inválida';end if;
if escopo='padrao' then update public.cda_orc_padroes_tipo set conteudo=novo,atualizado_em=now() where id=registro and conteudo=anterior;
elsif escopo='projeto' then update public.cda_orc_cadastros_projeto set conteudo=novo where id=registro and conteudo=anterior and chave<>'categorias';
else raise exception 'Escopo inválido';end if;
get diagnostics n=row_count;if n<>1 then raise exception 'Cadastro alterado por outra sessão ou sem permissão; reabra antes de salvar';end if;return true;end;$$;
revoke all on function public.cda_orc_salvar_cadastro(text,uuid,jsonb,jsonb) from public,anon;grant execute on function public.cda_orc_salvar_cadastro(text,uuid,jsonb,jsonb) to authenticated;